<script lang="ts">let {onkey,onpeek,disabled=false}:{onkey:(key:string)=>void,onpeek:()=>void,disabled?:boolean}=$props();let pressed=$state('');function press(key:string){pressed=key;onkey(key);setTimeout(()=>pressed='',150)}</script><div class="keyboard" aria-label="Practice keyboard">{#each ['QWERTYUIOP','ASDFGHJKL','ZXCVBNM'] as row}<div class="keyrow">{#each row.split('') as key}<button class="key" class:pressed={pressed===key} {disabled} onclick={()=>press(key)}>{key}</button>{/each}</div>{/each}<div class="keyrow"><button class="peek" {disabled} onclick={onpeek}>Peek</button>{#each '1234567890'.split('') as key}<button class="number-key" {disabled} onclick={()=>press(key)}>{key}</button>{/each}</div></div>
